mkdir -p /tmp/sv-c409b3a8a3df452394cca59e6af307c5/typed-meta && cd /tmp/sv-c409b3a8a3df452394cca59e6af307c5/typed-meta && dotnet new console --framework net11.0 -o . --force -n TypedMeta >/dev/null 2>&1 && cat > Program.cs << 'EOF'
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed metadata retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata: {personInfo.Type.Name}, kind = {personInfo.Kind}");

// 2. Probe without throwing — TryGetTypeInfo returns false when unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded: {info!.Type.Name}");

// Use an options instance with NO resolver to show the "not available" branch
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (!empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person) on resolver-less options: not available (no exception)");

public record Person(string Name, int Age);
EOF
dotnet run

